import{z as n,x as D,o as E,c as d,q as l,j as r,D as e,d as s,s as o,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Feistel 与 DES 对照","description":"","frontmatter":{"title":"Feistel 与 DES 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/feistel-des.md","filePath":"cs/feistel-des.md","lastUpdated":1791413859000}'),p={name:"cs/feistel-des.md"};function B(h,a,S,c,f,m){const i=D("Mermaid");return E(),d("div",null,[a[2]||(a[2]=l('<h1 id="feistel-与-des-对照" tabindex="-1">Feistel 与 DES 对照 <a class="header-anchor" href="#feistel-与-des-对照" aria-label="Permalink to &quot;Feistel 与 DES 对照&quot;">​</a></h1><div class="epigraph"><p>Feistel 把块分成两半，一轮只用一边做轮函数再交叉；即使轮函数可逆性弱，整圈置换仍可逆。DES 是它的历史实例，块太小，今日不当新设计的默认。</p><footer>—— Feistel, Cryptography and Computer Privacy, Scientific American, 1973；NIST FIPS 46-3（历史）</footer></div><p>上一课<a href="/cs/aes-structure">AES</a>是代换–置换网络。缺口是<strong>另一族结构</strong>：Feistel，以及为何 DES 退出主干。<a href="/cs/dh-vs-rsa">DH 与 RSA 分工</a>不在这里重写；本课只对照块密码骨架。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AES 每圈都要 MixColumns 这类可逆线性层。Feistel：\\(R&#39;=L\\oplus F(R,k_i)\\)，\\(L&#39;=R\\)，解密即倒圈。DES：64 比特块、56 比特有效密钥，8 个 S 盒。缺口是结构对照与参数过时：生日界下 64 比特块在大量数据下碰撞；56 比特密钥可穷举。3DES 是权宜，不是目标。</p><p><span class="marginnote">数字实例：64 比特的块在生日界下，约 \\(2^{32}\\) 个块（\\(2^{32} \\times 8\\) 字节 \\(= 32\\) GiB）就可能看到两个相同密文块，大流量加密于是露馅；56 比特密钥约 \\(7 \\times 10^{16}\\) 种，1998 年一台专用机已在数天内穷举完，今天更是分钟级预算。</span></p><h3 id="不教破解步骤" tabindex="-1">不教破解步骤 <a class="header-anchor" href="#不教破解步骤" aria-label="Permalink to &quot;不教破解步骤&quot;">​</a></h3><p>本课不给差分分析或穷举的操作序列。只需：块小、密钥短是规格失败，换 AES/ChaCha，不要「加奇异 S 盒」当创新。</p><p><span class="marginnote">Luby–Rackoff：足够独立的伪随机轮函数可把 Feistel 做成 PRP。DES 的实际轮函数不是理想对象；分析史说明余量不够今日。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画三圈 Feistel 的交叉。对照 AES：无需把 F 做成可逆。列出 DES 的参数缺陷。指出许多「类 DES」只换 S 盒仍继承 64 比特块。</p>',12)),(E(),r(A,null,{default:e(()=>[o(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%B7%A6%E5%8D%8A%22%5D%20--%3E%20XOR%5B%22%E2%8A%95%20F(%E5%8F%B3%E5%8D%8A%2C%20%E8%BD%AE%E5%AF%86%E9%92%A5)%22%5D%0A%20%20R%5B%22%E5%8F%B3%E5%8D%8A%22%5D%20--%3E%20F%5B%22%E8%BD%AE%E5%87%BD%E6%95%B0%20F%22%5D%0A%20%20F%20--%3E%20XOR%0A%20%20XOR%20--%3E%20R2%5B%22%E6%96%B0%E5%8F%B3%E5%8D%8A%22%5D%0A%20%20R%20--%3E%20L2%5B%22%E6%96%B0%E5%B7%A6%E5%8D%8A%20%3D%20%E6%97%A7%E5%8F%B3%E5%8D%8A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"Feistel 把可逆性从 F 上卸走，实现友好。安全仍取决于 F 的混乱与扩散以及圈数。DES 作为历史对照：能讲清「为何要换」，不能当新协议的分组密码。后课流密码 ChaCha 走另一条路：不分组，直接造 PRG 式的密钥流。",-1)),(E(),r(A,null,{default:e(()=>[o(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E6%98%8E%E6%96%87%E5%88%86%E6%88%90%20L0%20%E4%B8%8E%20R0%22%5D%20--%3E%20K1%5B%22%E7%AC%AC%201%20%E8%BD%AE%E7%94%A8%E8%BD%AE%E5%AF%86%E9%92%A5%20k1%22%5D%0A%20%20K1%20--%3E%20K2%5B%22%E7%AC%AC%202%20%E8%BD%AE%E7%94%A8%20k2%22%5D%0A%20%20K2%20--%3E%20K3%5B%22%E7%AC%AC%203%20%E8%BD%AE%E7%94%A8%20k3%22%5D%0A%20%20K3%20--%3E%20CT%5B%22%E8%BE%93%E5%87%BA%E5%AF%86%E6%96%87%E4%B8%A4%E5%8D%8A%22%5D%0A%20%20CT%20--%3E%20D3%5B%22%E8%A7%A3%E5%AF%86%E7%AC%AC%201%20%E8%BD%AE%E7%94%A8%20k3%22%5D%0A%20%20D3%20--%3E%20D2%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E7%94%A8%20k2%22%5D%0A%20%20D2%20--%3E%20D1%5B%22%E6%9C%80%E5%90%8E%E4%B8%80%E8%BD%AE%E7%94%A8%20k1%22%5D%0A%20%20D1%20--%3E%20PT%5B%22%E8%BF%98%E5%8E%9F%20L0%20%E4%B8%8E%20R0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">直觉类比：Feistel 解密像把录像带倒着放——电路里每个零件（轮函数、异或、交换）原封不动，唯一变化是轮密钥按相反顺序喂进去。这就是「轮函数不必可逆，整圈却可逆」的工程红利：加密解密能共用同一份硬件或代码。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 3DES 的 EDE 细节写成推荐。不要在新系统里启用 DES。下一课 ChaCha20：ARX 软件流密码，对照 AES 的硬件友好 SPN。</p><p><span class="marginnote">常见误区：初学者容易以为「DES 跑三遍（3DES）就补回了安全」。实际上中间相遇攻击让它只有约 112 位强度而非 \\(56 \\times 3 = 168\\) 位，而且块仍是 64 比特，生日界的坑一点没填。3DES 只是兼容旧数据的权宜，新设计直接选 AES 或 ChaCha20。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AES 是 SPN；Feistel 用交叉使整圈可逆。</li><li>DES 块 64、密钥 56，规格上已退出默认。</li><li>Luby–Rackoff 说明理想轮函数下 Feistel 可成 PRP。</li><li>ChaCha20 是下一条软件向密钥流。</li><li>出处：Feistel, 1973；FIPS 46；Luby and Rackoff；对照 FIPS 197。</li></ul>',6))])}const C=n(p,[["render",B]]);export{u as __pageData,C as default};
